package util; import org.apache.commons.validator.routines.EmailValidator; public final class Helper{private Helper(){} public static boolean isStringNull(String s){return s==null||s.trim().isEmpty();} public static boolean isEmailValid(String e){return !isStringNull(e)&&EmailValidator.getInstance().isValid(e);} public static boolean isPhoneValid(String p){return !isStringNull(p)&&p.matches("^(\\+27|27|0)[6-8][0-9]{8}$");} public static boolean isStreetAddressValid(String s){return !isStringNull(s)&&s.matches("\\d+");} public static boolean isPositive(double v){return v>0;} public static boolean isNonNegative(double v){return v>=0;}}